  const whyRow = (t, a) => '<div style="padding: 8px 0; border-top: 1px solid ' + K.line2 + '; font-size: 13px; line-height: 19px;"><div style="font-weight: 600;">' + t + '</div><div style="color: ' + K.muted + '; margin-top: 1px;">' + a + '</div></div>';
