  const D4 = '<figure style="margin: 0;"><figcaption style="font-size: 17px; font-weight: 600; margin-bottom: 6px;">4 · Phone: the ask is a comment inside her walk</figcaption><div style="font-size: 14.5px; line-height: 22px; color: #3B4540; margin-bottom: 14px; min-height: 66px;">The live Inspection walk. The General Manager&rsquo;s ask sits at the top like a pen note, the five sows carry a tag in the list, and scoring one is the usual record on that pig. My day stays at tasks and units.</div>' + walkPhone + '</figure>';
